package com.primehr.migration;
import org.junit.jupiter.api.Test;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.Set;import static org.assertj.core.api.Assertions.assertThat;
class SuccessionV52MigrationParityTest{@Test void pairedMigrationsHaveMatchingContinuityAndReferralStructures()throws Exception{String p=read("db/migration/postgresql/V52__succession_continuity_rsp_referral.sql").toLowerCase(),s=read("db/migration/sqlserver/V52__succession_continuity_rsp_referral.sql").toLowerCase();Set<String>names=Set.of("succession_continuity_plan","succession_bench_coverage_entry","succession_rsp_referral_packet","succession_rsp_referral_event","ix_succ_continuity_position","ix_succ_bench_plan","ix_succ_rsp_referral_status","ix_succ_rsp_referral_event");for(String m:Set.of(p,s)){assertThat(m).contains(names.toArray(String[]::new));assertThat(m).doesNotContain("create application","shortlist_candidate","selection_decision","appointment_action","promotion_action","payroll_action","drop table","delete from");}}private String read(String path)throws IOException{try(var in=getClass().getClassLoader().getResourceAsStream(path)){if(in==null)throw new IOException(path);return new String(in.readAllBytes(),StandardCharsets.UTF_8);}}}
